func TestPlanInitialFleetRespectsTotalCeiling(test *testing.T) {
	tests := []struct {
		name        string
		rps         int
		regions     int
		initial     int
		ceiling     int
		wantPer     int
		wantRegions int
		wantError   bool
	}{
		{name: "two regions", rps: 40_000, regions: 2, ceiling: 24, wantPer: 4, wantRegions: 2},
		{name: "small run", rps: 5_000, regions: 9, ceiling: 6, wantPer: 1, wantRegions: 1},
		{name: "rounding at ceiling", rps: 1_000_000, regions: 9, ceiling: 200, wantPer: 25, wantRegions: 8},
		{name: "manual count", rps: 5_000, regions: 2, initial: 3, ceiling: 6, wantPer: 3, wantRegions: 2},
		{name: "manual overflow", rps: 5_000, regions: 2, initial: 3, ceiling: 5, wantError: true},
		{name: "target exceeds ceiling", rps: 40_000, regions: 2, ceiling: 7, wantError: true},
		{name: "per region cap", rps: 5_000, regions: 1, initial: 201, ceiling: 500, wantError: true},
		{name: "unresolved regions", rps: 5_000, ceiling: 10, wantError: true},
	}
	for _, testCase := range tests {
		test.Run(testCase.name, func(test *testing.T) {
			profile := sampleProfile(testCase.rps, config.PatternKeepaliveBurst)
			profile.Fleet.Regions = make([]string, testCase.regions)
			profile.Fleet.InitialVMCount = testCase.initial
			profile.Fleet.MaxVMCount = testCase.ceiling
			perRegion, regionCount, err := PlanInitialFleet(profile)
			if testCase.wantError {
				if err == nil {
					test.Fatal("expected sizing rejection")
				}
				return
			}
			if err != nil {
				test.Fatal(err)
			}
			if perRegion != testCase.wantPer || regionCount != testCase.wantRegions {
				test.Fatalf("got %d per region across %d regions, want %d across %d", perRegion, regionCount, testCase.wantPer, testCase.wantRegions)
			}
			if perRegion*regionCount > profile.Fleet.MaxVMCount {
				test.Fatal("initial allocation exceeded fleet ceiling")
			}
		})
	}
}
